// XLWebEngineUI: runtime-only optional Windows API; no hard DLL import.
template<class... Args>
static HRESULT xl_optional_DXGIGetDebugInterface1(Args... args) {
    struct API {
        HMODULE module = nullptr;
        decltype(&DXGIGetDebugInterface1) call = nullptr;
        API() {
            wchar_t path[32768]{};
            UINT length = GetSystemDirectoryW(path, 32768);
            constexpr wchar_t suffix[] = L"\\dxgi.dll";
            if (length && length + sizeof(suffix) / sizeof(wchar_t) < 32768) {
                for (size_t i = 0; i < sizeof(suffix) / sizeof(wchar_t); ++i) path[length + i] = suffix[i];
                module = LoadLibraryW(path);
                if (module) call = reinterpret_cast<decltype(call)>(GetProcAddress(module, "DXGIGetDebugInterface1"));
            }
        }
        ~API() { if (module) FreeLibrary(module); }
    };
    static const API api;
    return api.call ? api.call(args...) : E_NOINTERFACE;
}

